// New creates a Limiter with the given burst capacity and refill rate
// (tokens per second). The bucket starts full.
func New(burst int, rate float64) (*Limiter, error) {
	return NewWithClock(burst, rate, RealClock)
}

// NewWithClock is New with an injectable clock.
func NewWithClock(burst int, rate float64, clock Clock) (*Limiter, error) {
	if burst <= 0 || rate <= 0 {
		return nil, ErrInvalidConfig
	}
	if clock == nil {
		clock = RealClock
	}
	return &Limiter{
		tokens: float64(burst),
		last:   clock.Now(),
		burst:  burst,
		rate:   rate,
		clock:  clock,
	}, nil
}

// Allow reports whether a single token is available.
func (l *Limiter) Allow() bool { return l.AllowN(1) }

// AllowN reports whether n tokens are available at the current instant,
// consuming them if so. n must be positive; AllowN returns false for n <= 0.
func (l *Limiter) AllowN(n int) bool {
	if n <= 0 {
		return false
	}
	l.mu.Lock()
	defer l.mu.Unlock()

	now := l.clock.Now()
	elapsed := now.Sub(l.last).Seconds()
	if elapsed > 0 {
		l.tokens += elapsed * l.rate
		if l.tokens > float64(l.burst) {
			l.tokens = float64(l.burst)
		}
		l.last = now
	}
	if float64(n) > l.tokens {
		return false
	}
	l.tokens -= float64(n)
	return true
}

// Burst returns the configured burst capacity.
func (l *Limiter) Burst() int { return l.burst }

// Rate returns the configured refill rate in tokens per second.
func (l *Limiter) Rate() float64 { return l.rate }
