// Package ratelimit implements a concurrency-safe token-bucket rate limiter.
package ratelimit

import (
	"errors"
	"fmt"
	"sync"
	"time"
)

// Clock abstracts time for testability.
type Clock interface {
	Now() time.Time
}

type realClock struct{}

func (realClock) Now() time.Time { return time.Now() }

// Limiter is a concurrency-safe token-bucket rate limiter.
// Tokens refill continuously at rate TokensPerInterval per Interval.
type Limiter struct {
	mu sync.Mutex

	tokens       float64
	burst        float64
	tokensPerInt float64
	interval     time.Duration
	last         time.Time
	clock        Clock
}

// Config describes the limiter's refill behavior and capacity.
type Config struct {
	// TokensPerInterval is the number of tokens added per Interval.
	TokensPerInterval float64
	// Interval is the refill period. Must be > 0.
	Interval time.Duration
	// Burst is the maximum number of tokens the bucket can hold.
	Burst float64
}

// New creates a Limiter starting full (Burst tokens available).
func New(cfg Config) (*Limiter, error) {
	return NewWithClock(cfg, realClock{})
}

// NewWithClock creates a Limiter using the provided Clock.
func NewWithClock(cfg Config, clock Clock) (*Limiter, error) {
	if clock == nil {
		return nil, errors.New("ratelimit: nil clock")
	}
	if cfg.Interval <= 0 {
		return nil, errors.New("ratelimit: Interval must be > 0")
	}
	if cfg.TokensPerInterval <= 0 {
		return nil, errors.New("ratelimit: TokensPerInterval must be > 0")
	}
	if cfg.Burst <= 0 {
		return nil, errors.New("ratelimit: Burst must be > 0")
	}
	return &Limiter{
		tokens:       cfg.Burst,
		burst:        cfg.Burst,
		tokensPerInt: cfg.TokensPerInterval,
		interval:     cfg.Interval,
		last:         clock.Now(),
		clock:        clock,
	}, nil
}

// refill advances the bucket to time now.
func (l *Limiter) refill(now time.Time) {
	elapsed := now.Sub(l.last)
	if elapsed <= 0 {
		return
	}
	l.tokens += elapsed.Seconds() / l.interval.Seconds() * l.tokensPerInt
	if l.tokens > l.burst {
		l.tokens = l.burst
	}
	l.last = now
}

// AllowN reports whether n tokens may be consumed at time now.
func (l *Limiter) AllowN(now time.Time, n int) bool {
	if n < 0 {
		return false
	}
	l.mu.Lock()
	defer l.mu.Unlock()
	l.refill(now)
	need := float64(n)
	if l.tokens >= need {
		l.tokens -= need
		return true
	}
	return false
}

// Allow reports whether one token may be consumed now.
func (l *Limiter) Allow() bool {
	return l.AllowN(l.clock.Now(), 1)
}

// Tokens returns the current number of available tokens (for observability).
func (l *Limiter) Tokens() float64 {
	l.mu.Lock()
	defer l.mu.Unlock()
	l.refill(l.clock.Now())
	return l.tokens
}

// RetryAfter returns the duration until n tokens would be available,
// or an error if n exceeds Burst (never satisfiable).
func (l *Limiter) RetryAfter(n int) (time.Duration, error) {
	if n < 0 {
		return 0, fmt.Errorf("ratelimit: negative n")
	}
	l.mu.Lock()
	defer l.mu.Unlock()
	now := l.clock.Now()
	l.refill(now)
	need := float64(n) - l.tokens
	if need <= 0 {
		return 0, nil
	}
	if float64(n) > l.burst {
		return 0, fmt.Errorf("ratelimit: n=%d exceeds burst=%v", n, l.burst)
	}
	perSec := l.tokensPerInt / l.interval.Seconds()
	return time.Duration(need / perSec * float64(time.Second)), nil
}
