func TestRetryAfter(t *testing.T) {
	start := time.Date(2024, 1, 1, 0, 0, 0, 0, time.UTC)
	c := &fakeClock{t: start}
	l := mustLimiter(t, Config{TokensPerInterval: 1, Interval: time.Second, Burst: 1}, c)

	if !l.Allow() {
		t.Fatal("first Allow should succeed")
	}
	d, err := l.RetryAfter(1)
	if err != nil {
		t.Fatalf("RetryAfter: %v", err)
	}
	if d != time.Second {
		t.Fatalf("RetryAfter = %v, want 1s", d)
	}
	if _, err := l.RetryAfter(5); err == nil {
		t.Fatal("expected error when n exceeds burst")
	}
	c.Advance(time.Second)
	if !l.Allow() {
		t.Fatal("Allow should succeed after waiting RetryAfter")
	}
}

func TestConcurrentAllow(t *testing.T) {
	c := &fakeClock{t: start}
	l := mustLimiter(t, Config{TokensPerInterval: 1000, Interval: time.Second, Burst: 100}, c)
	const goroutines = 50
	results := make(chan bool, goroutines)
	for i := 0; i < goroutines; i++ {
		go func() { results <- l.Allow() }()
	}
	allowed := 0
	for i := 0; i < goroutines; i++ {
		if <-results {
			allowed++
		}
	}
	if allowed != 100 {
		t.Fatalf("allowed = %d, want 100", allowed)
	}
}
